To implement `mergeDeep(a, b)` without mutating either input, I will create a recursive function that handles plain objects and arrays separately. For plain objects, it will iterate over keys from both inputs, recursively merging nested objects and replacing primitives or arrays with those from `b`. For arrays, since deep merging is ambiguous (index-based vs. replace), I'll follow the common convention of replacing arrays entirely with those from `b`. Edge cases include handling non-plain objects (e.g., Dates, Maps), null/undefined values, and ensuring circular references don’t cause infinite recursion (though for simplicity here, we’ll assume no circular references as they’re complex to handle robustly without external libraries).

ANSWER:
```javascript
function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function mergeDeep(a, b) {
  if (isPlainObject(a) && isPlainObject(b)) {
    const result = {};
    const keys = new Set([...Object.keys(a), ...Object.keys(b)]);
    for (const key of keys) {
      if (key in a && key in b) {
        result[key] = mergeDeep(a[key], b[key]);
      } else if (key in a) {
        result[key] = a[key];
      } else {
        result[key] = b[key];
      }
    }
    return result;
  } else if (Array.isArray(a) && Array.isArray(b)) {
    // Replace arrays entirely for simplicity
    return b.slice();
  } else if (Array.isArray(a)) {
    return a.slice();
  } else if (Array.isArray(b)) {
    return b.slice();
  } else {
    // For primitives, null, undefined, or non-plain objects, replace with b
    return b;
  }
}

