  if (arr.length === 0) return [];
  const n = arr.length;
  k = ((k % n) + n) % n; // Normalize k to be within [0, n-1]
  if (k === 0) return arr.slice();
  const rotated = new Array(n);
  for (let i = 0; i < n; i++) {
