  p99: { maxLatencyMs: 500, description: '99th percentile latency must remain under 500ms' }
};

export function handleRegression(metricName, observedValue, threshold) {
  if (observedValue > threshold) {
    console.warn(`[PERF REGRESSION] ${metricName} is ${observedValue}ms (threshold: ${threshold}ms)`);
    // Trigger alerting, rollback if critical, and initiate root-cause analysis
    return { action: 'investigate', severity: observedValue > threshold * 2 ? 'critical' : 'warning' };
  }
  return { action: 'ok' };
}

