To implement infinite scroll in React Native using FlatList, I’ll use the `onEndReached` callback to trigger loading more data when the user scrolls near the end of the list, and set `onEndReachedThreshold` to define how close to the end (as a fraction of visible list length) the scroll position must be before `onEndReached` fires. Edge cases include preventing duplicate requests (using a loading flag), handling empty or error states gracefully, and ensuring the list doesn’t trigger `onEndReached` repeatedly when data is already loading or exhausted.

ANSWER:
```jsx
import React, { useState, useEffect, useCallback } from 'react';
import { FlatList, ActivityIndicator, Text, View, StyleSheet } from 'react-native';

const InfiniteScrollFlatList = () => {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);

  const fetchItems = async (pageNum) => {
    // Simulate API call
    return new Promise((resolve) => {
      setTimeout(() => {
        if (pageNum > 5) {
          resolve([]);
        } else {
          const newItems = Array.from({ length: 10 }, (_, i) => ({
            id: (pageNum - 1) * 10 + i,
            title: `Item ${(pageNum - 1) * 10 + i}`,
          }));
          resolve(newItems);
        }
      }, 500);
    });
  };

  const loadMore = useCallback(async () => {
    if (loading || !hasMore) return;

    setLoading(true);
    try {
      const newItems = await fetchItems(page);
      if (newItems.length === 0) {
        setHasMore(false);
      } else {
        setData((prevData) => [...prevData, ...newItems]);
        setPage((prevPage) => prevPage + 1);
      }
    } catch (error) {
      console.error('Error loading more items:', error);
    } finally {
      setLoading(false);
    }
  }, [loading, hasMore, page]);

  const renderItem = ({ item }) => (
    <View style={styles.item}>
      <Text>{item.title}</Text>
    </View>
  );

  const ListFooterComponent = () => {
    if (!loading) return null;
    return (
      <View style={styles.footer}>
        <ActivityIndicator size="large" />
      </View>
    );
  };

  return (
    <FlatList
      data={data}
      renderItem={renderItem}
      keyExtractor={(item) => item.id.toString()}
      onEndReached={loadMore}
      onEndReachedThreshold={0.5}
      ListFooterComponent={ListFooterComponent}
    />
  );
};

const styles = StyleSheet.create({
  item: {
    padding: 16,
    borderBottomWidth: 1,
    borderColor: '#ddd',
  },
  footer: {
    paddingVertical: 20,
    alignItems: 'center',
  },
});

export default InfiniteScrollFlatList;
```

